/**
 * Emitters for the parts of a script that every farm mode shares: metadata,
 * state, team/battle helpers, route tables, `onStart`, `onPathAction`, and the
 * message/summary callbacks.
 *
 * Mode strategies compose these and contribute only the wild-encounter policy.
 * Each emitter is guarded by the feature analysis in {@link analyseNeeds} so the
 * generated file never contains a helper nothing calls.
 */

import { luaKey, luaNumber, luaString, section } from '../core/lua-writer.js';
import { splitList, toStringList } from '../domain/config.js';
import {
  CONDITION_HELPERS,
  collectConditionHelpers,
  emitCondition,
  isEmptyCondition,
} from '../domain/condition.js';
import { hasTrappedEscape } from './battle.js';

/** Host sentinel for "the opponent has no status condition". */
const NO_STATUS_LITERAL = '""';

/**
 * @typedef {import('./route-plan.js').RoutePlan} RoutePlan
 * @typedef {import('../core/lua-writer.js').LuaWriter} LuaWriter
 *
 * @typedef {object} Needs
 * @property {string[]} moves          moves the battle plan may try to use
 * @property {boolean} slotHelpers     `slotWithMove` / `useMoveFromAnySlot` required
 * @property {boolean} ppHelper        `ppLeft` required
 * @property {boolean} mounts          a mount is configured
 * @property {boolean} breaks          scheduled breaks are on
 * @property {boolean} counters        session counters are logged
 * @property {boolean} trapFlag        the trapped flag is read somewhere
 * @property {boolean} relogEscape     the relog trap escape is emitted
 * @property {boolean} statusHelper    `opponentStatused` required
 * @property {boolean} onceFlags      the once-per-battle table `F` is used
 * @property {boolean} teamUpkeep     out-of-battle team management is emitted
 * @property {boolean} zoneReroll     a zone rotation is triggered by an event
 * @property {boolean} stopUpkeep     at least one stop emits a branch
 * @property {Set<string>} conditionHelpers helper ids the condition trees need
 *
 * @typedef {object} EmitContext
 * @property {object} config
 * @property {RoutePlan} plan
 * @property {Needs} needs
 * @property {import('./zones.js').ZonePlan} zones
 * @property {import('./team.js').TeamPlan} team
 */

/**
 * Work out which helpers the configuration actually needs.
 *
 * @param {object} config
 * @param {RoutePlan} plan
 * @param {import('./mode-registry.js').ModeTraits} modeTraits
 * @returns {Needs}
 */
export function analyseNeeds(config, plan, modeTraits) {
  const moves = [];
  if (modeTraits.usesWeaken && config.battle.weaken.mode === 'falseSwipe') {
    const move = String(config.battle.weaken.move ?? '').trim();
    if (move) moves.push(move);
  }
  if (modeTraits.usesBalls) {
    for (const move of config.battle.status.moves) {
      if (move && !moves.includes(move)) moves.push(move);
    }
  }

  const statusGated = modeTraits.usesBalls
    && (config.battle.status.requireBeforeBall
      || config.battle.balls.some((ball) => ball.condition === 'status'));

  // The escape lives on the not-wanted path, which modes that engage every
  // encounter do not have.
  const escapes = !modeTraits.engagesEveryEncounter && hasTrappedEscape(config);

  // A custom guard replaces the two simple healing conditions, so the simple
  // PP helper is only needed when the guard is not in use.
  const usesCustomGuard = !isEmptyCondition(config.team.customGuard);

  return {
    moves,
    usesCustomGuard,
    onceFlags: false,
    teamUpkeep: false,
    zoneReroll: false,
    stopUpkeep: false,
    conditionHelpers: collectConditionHelpers(config.team.customGuard),
    slotHelpers: moves.length > 0,
    ppHelper: !usesCustomGuard && config.team.healOnPPOut && moves.length > 0,
    mounts: toStringList(config.mounts.land).length > 0
      || toStringList(config.mounts.water).length > 0,
    breaks: Boolean(config.safety.breaks.enabled),
    counters: Boolean(config.logging.counters),
    trapFlag: moves.length > 0 || escapes,
    relogEscape: escapes && config.safety.onTrapped === 'relog',
    statusHelper: statusGated || (modeTraits.usesBalls && config.battle.status.moves.length > 0),
  };
}

/**
 * Script name/author/description plus an explanatory banner.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitPreamble(writer, { config, plan }) {
  writer.comment('Generated by the PROCatchem Script Builder.');
  writer.comment('moveToMap() is retired by the host, so every map change below steps onto a');
  writer.comment('warp cell with moveToCell(x, y) taken from your link_graph.txt.');
  if (plan.kind === 'here') {
    writer.comment('Route mode: hunt on whichever map the bot is standing on.');
  }
  writer.blank();
  writer.line(`name        = ${luaString(config.meta.name)}`);
  writer.line(`author      = ${luaString(config.meta.author)}`);
  writer.line(`description = ${luaString(config.meta.description)}`);
  writer.blank();
}

/**
 * Mutable script state.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitState(writer, { needs }) {
  section(writer, 'Session state');
  if (needs.trapFlag) {
    writer.line('local trapped     = false -- set by onBattleMessage when switching is blocked');
  }
  if (needs.counters) {
    writer.line('local wildSeen    = 0');
    writer.line('local shinySeen   = 0');
    writer.line('local caught      = 0');
    writer.line('local startMoney  = 0');
  }
  if (needs.breaks) {
    writer.line('local nextBreakAt = 0 -- os.time() of the next scheduled break');
    writer.line('local breakUntil  = 0 -- os.time() the current break ends');
  }
  if (needs.relogEscape) {
    writer.line('local relogArmed  = false');
  }
  if (needs.onceFlags) {
    writer.line('local F           = {} -- once-per-battle step flags, cleared between battles');
  }
  writer.blank();
}

/**
 * `slotWithMove`, `useMoveFromAnySlot`, and `opponentStatused`.
 *
 * `ppLeft` is deliberately not here: the condition-helper emitter owns it, so
 * there is exactly one definition whether it is a healing clause or a condition
 * that asks for it.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitTeamHelpers(writer, { needs }) {
  if (!needs.slotHelpers && !needs.statusHelper) return;
  section(writer, 'Helpers');

  if (needs.slotHelpers) {
    writer.comment('First usable slot that still has PP for `move`, or nil.');
    writer.fn('slotWithMove(move)', (w) => {
      w.useHosts(['getTeamSize', 'hasMove', 'isPokemonUsable', 'getRemainingPowerPoints']);
      w.block('for slot = 1, getTeamSize() do', (loop) => {
        loop.block(
          'if hasMove(slot, move) and isPokemonUsable(slot) and getRemainingPowerPoints(slot, move) >= 1 then',
          (inner) => inner.line('return slot'),
        );
      });
      w.line('return nil');
    }, { local: true });
    writer.blank();

    writer.comment('Use `move`, switching to the slot that owns it first. Returns false when');
    writer.comment('nothing can, so the caller falls through to its next tactic.');
    writer.fn('useMoveFromAnySlot(move)', (w) => {
      w.useHosts(['getActivePokemonNumber', 'useMove', 'sendPokemon']);
      w.line('local slot = slotWithMove(move)');
      w.line('if not slot then return false end');
      w.block('if getActivePokemonNumber() == slot then', (inner) => {
        inner.line('return useMove(move)');
      });
      w.line('if trapped then return false end -- cannot switch while trapped');
      w.line('return sendPokemon(slot)');
    }, { local: true });
    writer.blank();
  }

  if (needs.statusHelper) {
    writer.comment(`The host reports ${NO_STATUS_LITERAL} (not "NONE") when the opponent is clean.`);
    writer.fn('opponentStatused()', (w) => {
      w.useHost('getOpponentStatus');
      w.line('local status = getOpponentStatus()');
      w.line(`return status ~= nil and status ~= ${NO_STATUS_LITERAL}`);
    }, { local: true });
    writer.blank();
  }
}

/**
 * Local helpers that condition trees depend on.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitConditionHelpers(writer, { needs }) {
  const ids = [...(needs.conditionHelpers ?? [])].sort();
  if (!ids.length) return;
  section(writer, 'Condition helpers');
  for (const id of ids) {
    const helper = CONDITION_HELPERS[id];
    if (helper) helper.emit(writer);
  }
}

/**
 * Mount picker: first configured mount actually in the bag.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitMountHelper(writer, { config, needs }) {
  if (!needs.mounts) return;
  const land = toStringList(config.mounts.land);
  const water = toStringList(config.mounts.water);

  section(writer, 'Mounts');
  if (land.length) {
    writer.line(`local LAND_MOUNTS  = { ${land.map(luaString).join(', ')} }`);
  }
  if (water.length) {
    writer.line(`local WATER_MOUNTS = { ${water.map(luaString).join(', ')} }`);
  }
  writer.comment('First mount from the list that is in the bag; falls back to the first entry.');
  writer.fn('pickMount(list)', (w) => {
    w.useHost('hasItem');
    w.block('for _, mount in ipairs(list) do', (loop) => {
      loop.line('if hasItem(mount) then return mount end');
    });
    w.line('return list[1]');
  }, { local: true });
  writer.blank();
}

/**
 * Route tables, the leg selector, the `walk` helper, and stop upkeep.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitRoute(writer, context) {
  const { plan } = context;
  if (!plan.travels && !plan.stops.length) return;
  section(writer, 'Route');

  if (plan.travels) {
    writer.comment('Each entry is the cell to step on to leave that map toward the next one.');
    for (const leg of plan.legs) {
      emitHopTable(writer, hopTableName(leg, 'TO_FARM'), leg.toFarm);
      emitHopTable(writer, hopTableName(leg, 'TO_HEAL'), leg.toHeal);
    }
    writer.blank();

    if (plan.legs.length > 1) emitLegSelector(writer, plan);

    writer.comment('Take one hop along `hops`. Returns false when the bot is somewhere the');
    writer.comment('route does not cover, which the host reports as "no action executed".');
    writer.fn('walk(hops)', (w) => {
      w.useHosts(['getMapName', 'moveToCell']);
      w.line('local hop = hops[getMapName()]');
      w.line('if hop then return moveToCell(hop[1], hop[2]) end');
      w.line('return false');
    }, { local: true });
    writer.blank();
  }

  emitStopUpkeep(writer, context);
}

/**
 * Suffix a hop table with its leg, so the time-of-day legs do not collide.
 *
 * @param {import('./route-plan.js').RouteLeg} leg
 * @param {string} base
 * @returns {string}
 */
function hopTableName(leg, base) {
  return leg.id === 'day' ? base : `${base}_${leg.id.toUpperCase()}`;
}

/**
 * `activeLeg()` — which hunting map and hop tables apply right now.
 *
 * @param {LuaWriter} writer
 * @param {import('./route-plan.js').RoutePlan} plan
 */
function emitLegSelector(writer, plan) {
  writer.comment('The hunting map changes with the time of day.');
  writer.fn('activeLeg()', (w) => {
    for (const leg of plan.legs) {
      const values = `${luaString(leg.farmMap)}, ${hopTableName(leg, 'TO_FARM')}, ${hopTableName(leg, 'TO_HEAL')}`;
      if (!leg.guard) {
        w.line(`return ${values}`);
        continue;
      }
      // The guard is a host predicate such as isMorning().
      w.useHost(leg.guard.replace('()', ''));
      w.line(`if ${leg.guard} then return ${values} end`);
    }
  }, { local: true });
  writer.blank();
}

/**
 * Which configured stops will actually emit a branch.
 *
 * @param {import('./route-plan.js').RoutePlan} plan
 * @param {object} config
 * @param {boolean} hasLandMount
 * @returns {import('./route-plan.js').RouteStop[]}
 */
export function usableStops(plan, config, hasLandMount) {
  return plan.stops.filter((stop) => stop.terrain !== 'any'
    || stop.mount === 'off'
    || (stop.mount === 'force' && hasLandMount));
}

/**
 * Per-map mount and terrain handling for stops along the way.
 *
 * Both adjustments converge — once the bot is mounted (or on the right
 * terrain) the function stops acting and the route continues.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
function emitStopUpkeep(writer, { plan, config, needs }) {
  const hasLandMount = needs.mounts && toStringList(config.mounts.land).length > 0;
  const usable = usableStops(plan, config, hasLandMount);
  if (!usable.length) return;

  writer.comment('Maps that need the mount or the terrain adjusted before moving on.');
  writer.fn('stopUpkeep(map)', (w) => {
    for (const stop of usable) {
      w.block(`if map == ${luaString(stop.map)} then`, (inner) => {
        if (stop.mount === 'off') {
          inner.useHosts(['isMounted', 'disMount']);
          inner.line('if isMounted() then return disMount() end');
        } else if (stop.mount === 'force' && hasLandMount) {
          inner.useHosts(['isMounted', 'setMount']);
          inner.line('if not isMounted() then return setMount(pickMount(LAND_MOUNTS)) end');
        }
        if (stop.terrain === 'water') {
          inner.useHosts(['isSurfing', 'moveToWater']);
          inner.line('if not isSurfing() then return moveToWater() end');
        } else if (stop.terrain === 'land') {
          inner.useHosts(['isSurfing', 'moveToNormalGround']);
          inner.line('if isSurfing() then return moveToNormalGround() end');
        }
      });
    }
    w.line('return false');
  }, { local: true });
  writer.blank();
}

/**
 * @param {LuaWriter} writer
 * @param {string} name
 * @param {import('../domain/link-graph.js').Hop[]} hops
 */
function emitHopTable(writer, name, hops) {
  if (!hops.length) {
    writer.line(`local ${name} = {}`);
    return;
  }
  const width = Math.max(...hops.map((hop) => luaKey(hop.from).length));
  writer.block(`local ${name} = {`, (w) => {
    for (const hop of hops) {
      const key = luaKey(hop.from).padEnd(width);
      w.line(`${key} = { ${hop.x}, ${hop.y} }, -- -> ${hop.to}`);
    }
  }, '}');
}

/**
 * Break scheduling built on `os.time()`.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitBreaks(writer, { config, needs }) {
  if (!needs.breaks) return;
  const { everyMin, everyMax, lengthMin, lengthMax } = config.safety.breaks;

  section(writer, 'Scheduled breaks');
  writer.line(`local BREAK_EVERY_MIN  = ${luaNumber(everyMin, 10)} * 60`);
  writer.line(`local BREAK_EVERY_MAX  = ${luaNumber(everyMax, 30)} * 60`);
  writer.line(`local BREAK_LENGTH_MIN = ${luaNumber(lengthMin, 30)}`);
  writer.line(`local BREAK_LENGTH_MAX = ${luaNumber(lengthMax, 180)}`);
  writer.blank();

  writer.fn('scheduleNextBreak()', (w) => {
    w.line('nextBreakAt = os.time() + math.random(BREAK_EVERY_MIN, BREAK_EVERY_MAX)');
  }, { local: true });
  writer.blank();

  writer.comment('True while a break is running. Starts one when the timer comes due.');
  writer.fn('onBreak()', (w) => {
    w.line('local now = os.time()');
    w.line('if now < breakUntil then return true end');
    w.block('if nextBreakAt > 0 and now >= nextBreakAt then', (inner) => {
      inner.line('breakUntil = now + math.random(BREAK_LENGTH_MIN, BREAK_LENGTH_MAX)');
      inner.line('scheduleNextBreak()');
      inner.useHost('log');
      inner.line('log("Taking a break for " .. tostring(breakUntil - now) .. "s")');
      inner.line('return true');
    });
    w.line('return false');
  }, { local: true });
  writer.blank();
}

/**
 * `teamIsReady()` — whether the script can keep farming or must go heal.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitTeamReady(writer, { config, needs }) {
  const clauses = [];
  const usableFloor = config.team.healBelowUsable;
  if (usableFloor !== null && usableFloor > 0) {
    clauses.push(`getUsablePokemonCount() >= ${luaNumber(usableFloor, 1)}`);
  }
  if (needs.ppHelper) {
    for (const move of needs.moves) {
      clauses.push(`ppLeft(${luaString(move)}) >= 1`);
    }
  }

  section(writer, 'Team readiness');
  writer.comment('False means: stop farming and go heal.');
  writer.fn('teamIsReady()', (w) => {
    if (needs.usesCustomGuard) {
      w.comment('Custom guard from the editor.');
      w.line(`return ${emitCondition(config.team.customGuard, w)}`);
      return;
    }
    if (!clauses.length) {
      w.comment('No healing rules configured, so the script never leaves the farm.');
      w.line('return true');
      return;
    }
    if (usableFloor !== null && usableFloor > 0) w.useHost('getUsablePokemonCount');
    w.line(`return ${clauses.join('\n    and ')}`);
  }, { local: true });
  writer.blank();
}

/**
 * `onStart` — mounts, counters, break schedule, AFK timeout.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitOnStart(writer, { config, needs }) {
  const land = toStringList(config.mounts.land);
  const water = toStringList(config.mounts.water);
  const afk = config.safety.afkTimeout;

  section(writer, 'Lifecycle');
  writer.fn('onStart()', (w) => {
    if (needs.counters) {
      w.useHost('getMoney');
      w.line('startMoney = getMoney()');
    }
    if (needs.mounts && config.mounts.applyOnStart) {
      if (land.length) {
        w.useHost('setMount');
        w.line('setMount(pickMount(LAND_MOUNTS))');
      }
      if (water.length) {
        w.useHost('setWaterMount');
        w.line('setWaterMount(pickMount(WATER_MOUNTS))');
      }
    }
    if (afk !== null && afk > 0) {
      w.useHost('setAfkTimeout');
      w.line(`setAfkTimeout(${luaNumber(afk, 0)})`);
    }
    if (needs.breaks) {
      w.line('math.randomseed(os.time())');
      w.line('scheduleNextBreak()');
    }
    w.useHost('log');
    w.line('log("Script started.")');
  });
  writer.blank();
}

/**
 * `onPathAction` — the out-of-battle loop.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitOnPathAction(writer, context) {
  const { config, plan, needs } = context;

  writer.fn('onPathAction()', (w) => {
    if (needs.trapFlag) {
      w.comment('Leaving a battle clears the trap flag.');
      w.line('trapped = false');
    }
    if (needs.onceFlags) {
      w.comment('This callback only runs between battles, so it is where once-per-battle resets.');
      w.line('F = {}');
    }
    // `map` is only read when the script has to tell maps apart. Hunting in
    // place with no Pokécenter never does, so declaring it there would leave an
    // unused local in the output.
    const readsMap = plan.travels
      || needs.stopUpkeep
      || (plan.kind === 'route' && Boolean(plan.farmMap || plan.pokecenterMap));
    if (readsMap) {
      w.useHost('getMapName');
      w.line('local map = getMapName()');
    }
    if (multiLeg(plan)) {
      w.line('local farmMap, toFarm, toHeal = activeLeg()');
    }
    w.blank();

    if (needs.stopUpkeep) {
      w.comment('Adjust mount and terrain before travelling on.');
      w.line('if stopUpkeep(map) then return true end');
      w.blank();
    }

    if (needs.breaks) {
      w.block('if onBreak() then', (inner) => {
        emitBreakTick(inner, context);
      });
      w.blank();
    }

    if (needs.teamUpkeep) {
      w.comment('Team management takes priority: it costs one frame, then farming resumes.');
      w.line('if teamUpkeep() then return true end');
      w.blank();
    }

    w.block('if teamIsReady() then', (inner) => {
      emitFarmTick(inner, context);
    });
    w.blank();
    w.comment('Team is spent — head back and heal.');
    emitHealTick(w, context);
  });
  writer.blank();
}

/**
 * What to do during a break: park somewhere without encounters.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
function emitBreakTick(writer, { plan }) {
  writer.comment('Stay logged in without triggering encounters.');
  if (plan.travels) {
    writer.useHost('moveToNormalGround');
    writer.block(`if map == ${luaString(plan.pokecenterMap)} then`, (inner) => {
      inner.line('return moveToNormalGround()');
    });
    writer.line(`return walk(${multiLeg(plan) ? 'toHeal' : 'TO_HEAL'})`);
    return;
  }
  writer.useHost('moveToNormalGround');
  writer.line('return moveToNormalGround()');
}

/**
 * The hunting half of `onPathAction`.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
function emitFarmTick(writer, context) {
  const { plan } = context;
  const target = multiLeg(plan) ? 'farmMap' : luaString(plan.farmMap);
  const table = multiLeg(plan) ? 'toFarm' : 'TO_FARM';

  if (!plan.travels) {
    if (plan.kind === 'route' && plan.farmMap) {
      writer.block(`if map == ${target} then`, (inner) => {
        emitFarmAction(inner, context);
      });
      writer.line('return false');
      return;
    }
    emitFarmAction(writer, context);
    return;
  }

  writer.block(`if map == ${target} then`, (inner) => {
    emitFarmAction(inner, context);
  });
  writer.line(`return walk(${table})`);
}

/**
 * The configured hunting action, with the surf guard in front of it.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
function emitFarmAction(writer, { config, zones }) {
  const { farmAction, farmArgs, surfFix } = config.route;
  const wantsWater = farmAction === 'moveToWater';

  if (surfFix && !wantsWater && !zones.active) {
    writer.useHosts(['isSurfing', 'moveToNormalGround']);
    writer.comment('Surfing when we want land encounters: step back onto dry ground first.');
    writer.line('if isSurfing() then return moveToNormalGround() end');
  }
  if (config.mounts.dismountOnFarm) {
    writer.useHosts(['isMounted', 'disMount']);
    writer.line('if isMounted() then return disMount() end');
  }
  if (zones.active) {
    writer.comment('Zones replace the plain hunting action.');
    writer.line('return farmZone()');
    return;
  }
  writer.line(`return ${renderFarmCall(farmAction, farmArgs, writer)}`);
}

/**
 * @param {string} action
 * @param {string} rawArgs
 * @param {LuaWriter} writer
 * @returns {string}
 */
function renderFarmCall(action, rawArgs, writer) {
  writer.useHost(action);
  if (action === 'moveToCell') {
    const [x, y] = splitList(rawArgs);
    return `moveToCell(${luaNumber(x, 0)}, ${luaNumber(y, 0)})`;
  }
  if (action === 'useItem') {
    return `useItem(${luaString(String(rawArgs ?? '').trim())})`;
  }
  return `${action}()`;
}

/**
 * The healing half of `onPathAction`.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
function emitHealTick(writer, context) {
  const { plan } = context;
  if (!plan.travels) {
    if (plan.kind === 'route' && plan.pokecenterMap) {
      writer.block(`if map == ${luaString(plan.pokecenterMap)} then`, (inner) => {
        emitHealAction(inner, context);
      });
      writer.line('return false');
      return;
    }
    emitHealAction(writer, context);
    return;
  }

  writer.block(`if map == ${luaString(plan.pokecenterMap)} then`, (inner) => {
    emitHealAction(inner, context);
  });
  writer.line(`return walk(${multiLeg(plan) ? 'toHeal' : 'TO_HEAL'})`);
}

/**
 * True when the route has more than one hunting destination, so the hop tables
 * are chosen at runtime rather than named directly.
 *
 * @param {RoutePlan} plan
 * @returns {boolean}
 */
function multiLeg(plan) {
  return plan.travels && plan.legs.length > 1;
}

/**
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
function emitHealAction(writer, { config, zones }) {
  const { healAction, healArgs } = config.route;
  writer.useHosts(['isSurfing', 'moveToNormalGround']);
  writer.line('if isSurfing() then return moveToNormalGround() end');
  if (zones.eventDriven && zones.mode === 'onHeal') {
    writer.comment('Healing is the trigger for picking a different zone.');
    writer.line('zoneReroll = true');
  }
  if (healAction === 'talkToNpcOnCell') {
    const [x, y] = splitList(healArgs);
    writer.useHost('talkToNpcOnCell');
    writer.line(`return talkToNpcOnCell(${luaNumber(x, 0)}, ${luaNumber(y, 0)})`);
    return;
  }
  writer.useHost('usePokecenter');
  writer.line('return usePokecenter()');
}

/**
 * `onBattleMessage` — trap detection, counters, shiny announcements.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitOnBattleMessage(writer, { config, needs, zones }) {
  const armsZoneReroll = zones.eventDriven && zones.mode === 'onWin';
  if (!needs.trapFlag && !needs.counters && !armsZoneReroll) return;

  const trapPhrases = [
    'wrapped',
    'You can not switch this Pokemon',
    'You failed to run away',
    'You can not run away',
    'You can not switch',
  ];

  writer.fn('onBattleMessage(message)', (w) => {
    w.useHost('stringContains');
    if (needs.trapFlag) {
      const test = trapPhrases
        .map((phrase) => `stringContains(message, ${luaString(phrase)})`)
        .join('\n       or ');
      w.block(`if ${test} then`, (inner) => {
        inner.line('trapped = true');
        if (needs.relogEscape) inner.line('relogArmed = true');
      });
    }
    if (armsZoneReroll) {
      w.comment('Winning a battle is the trigger for picking a different zone.');
      w.line('if stringContains(message, "You have won") then zoneReroll = true end');
    }
    if (needs.counters) {
      w.line('if stringContains(message, "A Wild SHINY ") then shinySeen = shinySeen + 1 end');
      w.line('if stringContains(message, "A Wild ") then wildSeen = wildSeen + 1 end');
      w.line('if stringContains(message, "Success! You caught") then caught = caught + 1 end');
      if (config.logging.announceShiny) {
        w.useHost('log');
        w.block('if stringContains(message, "A Wild SHINY ") then', (inner) => {
          inner.line('log("*** SHINY ENCOUNTER *** " .. message)');
        });
      }
    }
  });
  writer.blank();
}

/**
 * `onPause` — session summary.
 *
 * @param {LuaWriter} writer
 * @param {EmitContext} context
 */
export function emitOnPause(writer, { needs }) {
  if (!needs.counters) return;
  writer.fn('onPause()', (w) => {
    w.useHosts(['log', 'getMoney']);
    w.line('log("Wild seen: " .. wildSeen .. " | shiny: " .. shinySeen .. " | caught: " .. caught)');
    w.line('log("Money earned: " .. tostring(getMoney() - startMoney))');
  });
  writer.blank();
}
